// Prompt esatto di audit rapido per contratti e preventivi:
"Analizza esclusivamente il documento allegato come un revisore tecnico.
Estrai in 5 sezioni schematiche citando sempre pagina e paragrafo:
1) Oggetto e obblighi principali;
2) Rischi e clausole asimmetriche o penali;
3) Costi fissi, variabili o nascosti;
4) Scadenze di recesso e rinnovo automatico;
5) Passaggi ambigui o tabelle illeggibili da verificare a mano."

// Contratto minimo di passaggio tra Agente Ricercatore e Revisore:
{
  "fatti_verificati": ["voce + fonte o pagina"],
  "lacune_dichiarate": ["dato non presente nei documenti"],
  "stato_validazione": "approvato | da_rivedere",
  "max_iterazioni": 2
}

// Schema JSON rigoroso imposto al nodo di triage:
{
  "urgenza": "alta | media | bassa",
  "azione_richiesta": "stringa max 18 parole",
  "proposta_slot_minuti": 30,
  "richiede_conferma_umana": true
}

// Esempio concettuale di tokenizzazione BPE:
const input = "L'intelligenza artificiale apprende.";
// BPE scompone in sotto-token: ["L'", "intell", "igenza", " artificial", "e", " apprend", "e", "."]
// Mappati in indici interi del vocabolario: [1842, 45210, 8931, 23901, 260, 31204, 260, 13]

// Concetto di Low-Rank Adaptation (LoRA):
// W_aggiornato = W_originale + (A * B) * (alpha / rank)
// Dove rank (r) è tipicamente 8, 16 o 64, riducendo i parametri addestrabili a <1%

// Schema tipico di chiamata Tool (Function Calling):
{
  "name": "cerca_database_documenti",
  "arguments": {
    "query": "architettura transformer flashattention",
    "limite_risultati": 5
  }
}
